 assert.equal(parent.atlasHead,'aa13c067197cad87bd0a9b2da5549bc4b33bfdf7');assert.equal(parent.reviewBindingSha256,'5216ef1195e37903db9806b5c77d87f4ba1b141b1dbc82b0087651727fc3e429');const dir=site+'/dist/client/_next/static/css',files=fs.readdirSync(dir).filter(p=>p.startsWith('ClinicalReviewInbox.')&&p.endsWith('.css'));assert.equal(files.length,1);const css=fs.readFileSync(dir+'/'+files[0],'utf8');assert(css.includes('680px')&&css.includes('480px')&&css.includes('clinical-review-inbox-workbench'));write(stage+'/EMITTED_QUEUE_CSS.json',{path:'client/_next/static/css/'+files[0],sha256:hash(dir+'/'+files[0]),shortDesktopBoundsPresent:true,previewChanged:false});
