const evidence=[];function scan(dir,prefix=''){for(const e of fs.readdirSync(dir,{withFileTypes:true})){assert(!e.isSymbolicLink());const p=prefix+e.name;if(e.isDirectory())scan(dir+'/'+e.name,p+'/');else evidence.push({path:p,bytes:fs.statSync(dir+'/'+e.name).size,sha256:hash(dir+'/'+e.name)});}}for(const dir of ['checks','browser-before','browser-after'])scan(stage+'/'+dir,dir+'/');for(const p of ['PREPARATION.json','BROWSER_OBSERVATIONS.json','EMITTED_QUEUE_CSS.json'])evidence.push({path:p,bytes:fs.statSync(stage+'/'+p).size,sha256:hash(stage+'/'+p)});write(stage+'/EVIDENCE.json',{files:evidence,recipes:['improve-review-queue-20261024.mjs','qa-review-queue-short-desktop-20261024.jsx','seal-review-queue-short-desktop-20261024.mjs'].map(p=>({path:path.resolve(p),sha256:hash(p)})),localOnly:true});console.log(JSON.stringify({...receipt,evidence:stage+'/EVIDENCE.json',evidenceSha256:hash(stage+'/EVIDENCE.json')}));
